<?php require 'config.php'; $id=(int)($_GET['id']??0);$stmt=db()->prepare('SELECT p.*,c.name category_name FROM products p LEFT JOIN categories c ON c.id=p.category_id WHERE p.id=? AND p.is_active=1');$stmt->bind_param('i',$id);$stmt->execute();$product=$stmt->get_result()->fetch_assoc();if(!$product){http_response_code(404);exit('Product not found.');} if($_SERVER['REQUEST_METHOD']==='POST'){verify_csrf();$_SESSION['cart'][$id]=($_SESSION['cart'][$id]??0)+1;redirect('cart.php');} page_start($product['title'],'shop'); ?>
<section class="section-space"><div class="container"><div class="row g-5 align-items-center"><div class="col-lg-6"><div class="detail-art <?= e($product['cover_color']) ?>"><?= e($product['title']) ?></div></div><div class="col-lg-5 offset-lg-1"><div class="eyebrow"><?= e($product['category_name']??'Digital resource') ?></div><h1 class="display-5 mt-2"><?= e($product['title']) ?></h1><p class="lead text-muted mt-3"><?= e($product['description']) ?></p><div class="price display-6 my-4"><?= money((float)$product['price']) ?></div><form method="post"><input type="hidden" name="csrf" value="<?= csrf_token() ?>"><button class="btn btn-dark btn-lg btn-rounded px-4" type="submit">Add to cart <span class="ms-2">→</span></button></form><div class="border-top mt-5 pt-4 small text-muted">Instant access after checkout · Personal use license · Secure downloads</div></div></div></div></section><?php page_end(); ?>